solution.solution.cpp:
#include <string>
#include <vector>

struct Shape;

struct ShapeVTable
{
    double (*area)(const Shape&);
    std::string (*name)(const Shape&);
};

struct Shape
{
    const ShapeVTable* vptr;
    double a;
    double b;
};

double circleArea(const Shape& s) { return 3.14159265358979 * s.a * s.a; }
double rectArea(const Shape& s) { return s.a * s.b; }
std::string circleName(const Shape&) { return "circle"; }
std::string rectName(const Shape&) { return "rectangle"; }

const ShapeVTable kCircleTable{ &circleArea, &circleName };
const ShapeVTable kRectTable{ &rectArea, &rectName };

Shape makeCircle(double r) { return Shape{ &kCircleTable, r, 0.0 }; }
Shape makeRect(double w, double h) { return Shape{ &kRectTable, w, h }; }

double totalArea(const std::vector<Shape>& shapes)
{
    double total{ 0.0 };
    for (const Shape& s : shapes)
        total += s.vptr->area(s);        // the "virtual call": look up the slot, call it
    return total;
}

unitTests:
TEST("a rectangle") { const Shape r{ makeRect(3, 4) }; CHECK_NEAR(r.vptr->area(r), 12.0, 1e-9); CHECK_EQ(r.vptr->name(r), std::string("rectangle")); }
TEST("a circle") { const Shape c{ makeCircle(2) }; CHECK_NEAR(c.vptr->area(c), 12.566370614359, 1e-6); CHECK_EQ(c.vptr->name(c), std::string("circle")); }
TEST("shapes of a kind share one table") { CHECK(makeRect(1, 1).vptr == makeRect(5, 9).vptr); CHECK(makeRect(1, 1).vptr != makeCircle(1).vptr); }
TEST("total area dispatches per shape") { CHECK_NEAR(totalArea({ makeRect(2, 5), makeCircle(1), makeRect(1, 1) }), 14.14159265358979, 1e-6); }
TEST("no shapes") { CHECK_NEAR(totalArea({}), 0.0, 1e-12); }
TEST("dispatch really goes through the table")
{
    // A fake table that always reports area 100: totalArea must use it.
    static const ShapeVTable fake{ [](const Shape&) { return 100.0; }, [](const Shape&) { return std::string("fake"); } };
    CHECK_NEAR(totalArea({ Shape{ &fake, 1, 1 }, makeRect(1, 2) }), 102.0, 1e-9);
}

